// THE WORLD IN PICTURES — news-image-20261126
// Writes the entry image (1024x1024 PNG, 26 stories of Thu 26 Nov 2026)
// to MAKEFUN_OUTPUT_DIR/entry.png. Node 22, standard library only,
// no network: the image bytes are embedded below as base64.
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const PNG_B64 = "";

const outDir = process.env.MAKEFUN_OUTPUT_DIR ?? "./output";
mkdirSync(outDir, { recursive: true });
writeFileSync(join(outDir, "entry.png"), Buffer.from(PNG_B64, "base64"));
